const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const output = {
  event: 'github.workflow_completed',
  source: 'github',
  repo: body.repository?.full_name ?? body.repo ?? 'div0rce/cherry',
  timestamp: body.timestamp ?? body.workflow_run?.updated_at ?? body.pull_request?.updated_at ?? body.issue?.updated_at ?? new Date().toISOString(),
  payload: body,
  workflow: '01_ci_failure_compression',
  ok: true,
  status: 'accepted',
  summary: 'Normalized github.workflow_completed.',
  actions: []
};
return [{ json: output }];

const event = $input.first()?.json ?? {};
const fields = ["payload.workflow_run.conclusion","payload.workflow_run.html_url"];
const missing = fields.filter((field) => field.split('.').reduce((value, key) => value?.[key], event) === undefined);
const output = { ...event, valid: missing.length === 0, validationErrors: missing, status: missing.length === 0 ? event.status : 'failed', summary: missing.length === 0 ? event.summary : 'Payload missing required fields: ' + missing.join(', ') };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const run = event.payload?.workflow_run ?? {};
const conclusion = run.conclusion ?? 'unknown';
const text = [run.name, run.display_title, run.path, run.html_url].filter(Boolean).join(' ').toLowerCase();
const category = text.includes('lint') ? 'lint' : text.includes('typecheck') || text.includes('typescript') ? 'typecheck' : text.includes('test') ? 'test' : text.includes('build') ? 'build' : text.includes('closure') || text.includes('guardrail') ? 'repo-closure' : text.includes('migration') || text.includes('prisma') ? 'migration' : 'unknown';
const shouldProcess = conclusion === 'failure' || conclusion === 'timed_out' || conclusion === 'cancelled';
const workflowName = run.name ?? 'unknown workflow';
const branch = run.head_branch ?? 'unknown branch';
const sha = run.head_sha ?? 'unknown sha';
const url = run.html_url ?? '';
const title = '[ci:' + category + '] ' + workflowName + ' failed on ' + branch;
const output = { ...event, shouldProcess, failureCategory: category, workflowName, branch, sha, url, searchQuery: encodeURIComponent('repo:' + event.repo + ' is:issue is:open in:title "[ci:' + category + ']" "' + workflowName + '"'), issueBody: { title, labels: ['ci-failure', 'automation', 'needs-triage', category], body: 'Cherry CI failure compression.

Workflow: ' + workflowName + '
Branch: ' + branch + '
SHA: ' + sha + '
Category: ' + category + '
Run: ' + url + '

Suggested verification: npm run ci:verify

Advisory automation only.' }, commentBody: { body: 'Repeated CI failure.

Workflow: ' + workflowName + '
Branch: ' + branch + '
SHA: ' + sha + '
Category: ' + category + '
Run: ' + url }, openclawTask: { source: 'ci_failure', repo: event.repo, title, category, branch, sha, url, guardrails: ['npm run ci:verify', 'no Cherry finance truth mutation'] }, status: shouldProcess ? 'accepted' : 'ignored', summary: shouldProcess ? title : 'Workflow conclusion was ' + conclusion + '; ignoring.', actions: shouldProcess ? ['search_existing_issue', 'comment_or_create_issue', 'optional_openclaw_task', 'archive_event'] : [] };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ...event, workflow: event.workflow ?? '01_ci_failure_compression', sinkRouting: {
  discord: '{{ $env.DISCORD_WEBHOOK_URL }}', slack: '{{ $env.SLACK_WEBHOOK_URL }}', email: '{{ $env.EMAIL_WEBHOOK_URL }}', notion: '{{ $env.NOTION_WEBHOOK_URL }}', googleSheets: '{{ $env.GOOGLE_SHEETS_WEBHOOK_URL }}', linearJira: '{{ $env.LINEAR_JIRA_WEBHOOK_URL }}', githubProjects: '{{ $env.GITHUB_PROJECTS_WEBHOOK_URL }}', archive: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/events', incidentTimeline: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/incident-timeline' } };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: event.status ?? 'accepted', summary: event.summary ?? 'CI failure compressed.', actions: event.actions ?? [] };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: 'ignored', summary: event.summary ?? 'CI workflow did not fail; no action taken.', actions: event.actions ?? [] };
return [{ json: output }];
